# Builds site/data/tracks/21-maint.js from steps21.py and lessons21.py. SQL steps run one at a time
# through foundations/sql_exec.py on a fresh PlantDB (work_order included), as the SQL lane does;
# Python steps run in sequence, as one file, on PlantDB with the OEE track's v_hourly_barrels view.
# Checks: the first step's CREATE is the same as WORK_ORDER_DDL in sql_exec.py, and the Python
# MTBF and MTTR match the SQL step's. Needs BC_SQL_PASSWORD and the SQL Server container.
# Do not edit the JS file by hand.
#   python3 build21.py            write the track
#   python3 build21.py --check    report a difference, change nothing
import contextlib, io, json, os, re, subprocess, sys, tempfile, warnings
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(HERE.parent / "lib" / "pydb"))
sys.path.insert(0, str(HERE.parent / "foundations"))
import plantdb
from steps21 import CODE, LANG

def ddl():
    src = (HERE.parent / "foundations/sql_exec.py").read_text()
    return re.search(r'WORK_ORDER_DDL = """(.*?)"""', src, re.S).group(1)

if CODE["Create work_order"] != ddl():
    sys.exit("Create work_order differs from WORK_ORDER_DDL in sql_exec.py: keep them the same")

def lesson_code(track_file, title):
    js = ("const fs=require('fs'),vm=require('vm'),c={};c.BC={addLanguage(){},addGlossary(){},addLane(){},addTrack(t){c.t=t}};"
          "vm.createContext(c);vm.runInContext(fs.readFileSync(process.argv[1],'utf8'),c);"
          "console.log(JSON.stringify(c.t.lessons.find(l=>l.t===process.argv[2]).code))")
    return json.loads(subprocess.run(["node", "-e", js, str(ROOT / "site/data/tracks" / track_file), title], capture_output=True, text=True, check=True).stdout)

# A CREATE prints nothing, so its output is a check query on what it made, printed above its result.
AFTER = {"Create work_order": "SELECT COLUMN_NAME AS column_name, DATA_TYPE AS type, IS_NULLABLE AS nullable, COLUMN_DEFAULT AS default_value\n"
         "FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'work_order' ORDER BY ORDINAL_POSITION;"}
outs = {}
for title, lang in LANG.items():
    if lang == "sql":
        r = subprocess.run([sys.executable, str(HERE.parent / "foundations/sql_exec.py")], input=CODE[title], capture_output=True, text=True,
                           env={**os.environ, "BC_SQL_AFTER": AFTER.get(title, "")})
        if r.returncode:
            sys.exit(f"{title}: {r.stderr}")
        outs[title] = r.stdout.rstrip()

plantdb.reset([lesson_code("03-oee.js", "Hourly barrels view")])
plantdb.use_real_database()
warnings.filterwarnings("ignore", message="pandas only supports SQLAlchemy")
g = {}
with tempfile.TemporaryDirectory() as d:
    os.chdir(d)  # the workbook step saves an .xlsx
    for title, lang in LANG.items():
        if lang != "python":
            continue
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            exec(CODE[title], g)
        outs[title] = buf.getvalue().rstrip()

# The Python MTBF and MTTR must match the SQL step's, rounded the same way.
sql_rows = [l.split() for l in outs["MTBF and MTTR"].splitlines()[1:]]
for row in sql_rows:
    machine, mtbf, mttr = " ".join(row[:-4]), float(row[-2]), float(row[-1])
    py_r = g["m"].loc[machine]
    if round(py_r["mtbf"], 1) != mtbf or round(py_r["mttr"], 2) != mttr:
        sys.exit(f"MTBF/MTTR cross-check failed for {machine}: SQL {mtbf}/{mttr}, Python {py_r['mtbf']}/{py_r['mttr']}")

if "--outs" in sys.argv:
    for t, o in outs.items():
        print(f"===== {t}\n{o}")
    sys.exit(0)
print("Cross-checks: the CREATE matches the seed's DDL; Python MTBF and MTTR match SQL")

from lessons21 import TRACK, LESSONS
assert [t for t, *_ in LESSONS] == list(CODE), "lessons21.py and steps21.py list different steps"

def whole(k, code):
    pre = r"(?<!\w)" if re.match(r"\w", k) else ""
    post = r"(?!\w)" if re.search(r"\w$", k) else ""
    return re.search(pre + re.escape(k) + post, code) is not None

tpl = lambda x: "`" + x.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${") + "`"
js = lambda v: json.dumps(v, ensure_ascii=False)
lines = ["// Project track 21: Maintenance / CMMS (SQL and Python on the plant database)",
         "// Generated by tools/output-checks/track21-maint/build21.py from steps21.py and lessons21.py. Do not edit by hand.",
         "BC.addTrack({", f"  id: {js(TRACK['id'])},", f"  name: {js(TRACK['name'])},", f"  sub: {js(TRACK['sub'])},", "  lessons: ["]
for title, goal, about, terms in LESSONS:
    code = CODE[title]
    for k, *_ in terms:
        if k is not None and not whole(k, code):
            sys.exit(f"{title}: term key {k!r} is not in the code")
    lines += ["    {", f"      lang: {js(LANG[title])},", f"      file: {js(TRACK['files'][LANG[title]])},", f"      t: {js(title)},", f"      goal: {js(goal)},",
              f"      code: {tpl(code)},", f"      about: {js(about)},", "      terms: ["]
    lines += [f"        [{'null' if k is None else js(k)}, {js(a)}, {js(b)}]," for k, a, b in terms]
    lines += ["      ],", f"      out: {tpl(outs[title])},", "    },"]
lines += ["  ],", "});", ""]
text = "\n".join(lines)
target = ROOT / "site/data/tracks/21-maint.js"
if "--check" in sys.argv:
    same = target.exists() and target.read_text() == text
    print("21-maint.js is current" if same else "21-maint.js is stale: run python3 build21.py")
    sys.exit(0 if same else 1)
target.write_text(text)
print(f"wrote {target.relative_to(ROOT)}: {len(LESSONS)} steps")
